%[text] # Aufgabe 2.3: Koordinaten
%%
%[text] ## a) Gerade, Rechteck und Kreis einzeichnen
bild = imread('TestbildFernseher.jpg');

kreis    = [250 250 232];           % [x y radius]
rechteck = [55 90 390 320];          % [x y breite hoehe]
gerade   = [55 90 445 410];          % [x1 y1 x2 y2]

bildA = insertShape(bild,  'Circle',    kreis,    'Color', 'red',   'LineWidth', 3);
bildA = insertShape(bildA, 'Rectangle', rechteck, 'Color', 'green', 'LineWidth', 3);
bildA = insertShape(bildA, 'Line',      gerade,   'Color', 'blue',  'LineWidth', 3);

figure %[output:6328737f]
imshow(bildA) %[output:6328737f]
title('Kreis, Rechteck, Gerade') %[output:6328737f]
%%
%[text] ## b) Eigene Funktion myInsertCross
bildB = myInsertCross(bild, 300, 200, 20);

figure %[output:880a5415]
imshow(bildB) %[output:880a5415]
title('Kreuz bei x=300, y=200, Länge 20') %[output:880a5415]
%[text] 
%%
%[text] ## Funktion
function bild = myInsertCross(bild, x, y, l)
    h = l / 2;
    waagrecht = [x-h, y, x+h, y];
    senkrecht = [x, y-h, x, y+h];
    bild = insertShape(bild, 'Line', [waagrecht; senkrecht], 'Color', 'red', 'LineWidth', 2);
end

